from fractions import Fraction

def _det_bareiss(M):
    n = len(M)
    sign = 1
    prev = 1
    for k in range(n - 1):
        if M[k][k] == 0:
            found = False
            for i in range(k + 1, n):
                if M[i][k] != 0:
                    M[k], M[i] = M[i], M[k]
                    sign = -sign
                    found = True
                    break
            if not found:
                return 0
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                M[i][j] = (M[i][j] * M[k][k] - M[i][k] * M[k][j]) // prev
            M[i][k] = 0
        prev = M[k][k]
    return sign * M[n - 1][n - 1]

def _det_fraction(M):
    n = len(M)
    A = [[x if isinstance(x, Fraction) else Fraction(x) for x in row] for row in M]
    sign = 1
    det = Fraction(1)
    for k in range(n):
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    sign = -sign
                    break
            else:
                return 0
        piv = A[k][k]
        det *= piv
        for i in range(k + 1, n):
            f = A[i][k] / piv
            if f != 0:
                row_i, row_k = A[i], A[k]
                for j in range(k + 1, n):
                    row_i[j] -= f * row_k[j]
                row_i[k] = Fraction(0)
    result = det * sign
    if result.denominator == 1:
        return int(result)
    return float(result)

def solve(matrix):
    if not matrix:
        return 1
    n = len(matrix)
    rows = [list(r) for r in matrix]
    if any(len(r) != n for r in rows):
        return 0
    if all(isinstance(x, int) for r in rows for x in r):
        return _det_bareiss(rows)
    return _det_fraction(rows)

