def solve(a: str, b: str) -> int:
    """Return the Levenshtein edit distance between strings a and b.
    Uses O(n*m) DP.
    """
    n, m = len(a), len(b)
    # Initialize DP table
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j
    # Fill DP
    for i in range(1, n + 1):
        ai = a[i - 1]
        for j in range(1, m + 1):
            bj = b[j - 1]
            if ai == bj:
                cost = 0
            else:
                cost = 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,      # deletion
                dp[i][j - 1] + 1,      # insertion
                dp[i - 1][j - 1] + cost  # substitution
            )
    return dp[n][m]

def solve(s: str) -> int:
    """Return length of longest substring without repeating characters.
    Uses sliding window with a dictionary storing last seen index.
    """
    last_index = {}
    max_len = 0
    start = 0  # left boundary of current window
    for i, ch in enumerate(s):
        if ch in last_index and last_index[ch] >= start:
            # move start to one after the previous occurrence
            start = last_index[ch] + 1
        last_index[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

