def solve(s) -> bool:
    """Check balanced brackets.
    Accepts a string or any iterable yielding bracket characters. Non‑iterable inputs return False.
    """
    # Determine if s is iterable (including string). If not, invalid.
    try:
        iterator = iter(s)
    except TypeError:
        return False
    # For strings, iterating yields characters directly.
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in iterator:
        # We only care about bracket characters; ignore others.
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack
}

