def solve(intervals):
    """Merge overlapping or touching intervals.
    Intervals are given as [start, end] with start <= end.
    The result is sorted by start.
    """
    # Sort by start coordinate
    intervals = sorted(intervals, key=lambda iv: iv[0])
    merged = []
    for iv in intervals:
        if not merged:
            merged.append(iv[:])
        else:
            last = merged[-1]
            # Overlap or touch if current start <= last end
            if iv[0] <= last[1]:
                # Extend the last interval's end if needed
                last[1] = max(last[1], iv[1])
            else:
                merged.append(iv[:])
    return merged

