def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Handles malformed input gracefully by ignoring invalid entries.
    """
    # Validate input is iterable
    try:
        iterator = iter(meetings)
    except Exception:
        return 0
    valid = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        # Ensure numeric
        if not (isinstance(start, (int, float)) and isinstance(end, (int, float))):
            continue
        # Ensure start <= end; if not, swap to treat as valid interval
        if start > end:
            start, end = end, start
        valid.append((start, end))
    if not valid:
        return 0
    # Sort by end time, then start
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for start, end in valid:
        if start >= current_end:
            count += 1
            current_end = end
    return count

