def solve(grid):
    """Count islands (4-directionally connected 1s) in a possibly irregular grid.
    Returns 0 for empty grid or rows.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [set() for _ in range(rows)]  # set of visited column indices per row
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if y in visited[x]:
                continue
            visited[x].add(y)
            # explore neighbors
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows:
                    if ny < 0:
                        continue
                    if ny >= len(grid[nx]):
                        continue
                    if ny not in visited[nx] and grid[nx][ny] == 1:
                        stack.append((nx, ny))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and j not in visited[i]:
                dfs(i, j)
                count += 1
    return count

