def solve(n):
    """Return the count of prime numbers less than n.
    Uses simple trial division; works for all reasonable n values and avoids
    slice-index edge cases.
    """
    # Ensure n is an integer >= 0
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    def is_prime(k):
        if k < 2:
            return False
        if k % 2 == 0:
            return k == 2
        i = 3
        limit = int(k ** 0.5) + 1
        while i <= limit:
            if k % i == 0:
                return False
            i += 2
        return True
    count = 0
    for num in range(2, n):
        if is_prime(num):
            count += 1
    return count

