def solve(path):
    # Simplify a Unix absolute path.
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    return simplified

